// CSD_RATIONALE_BEGIN
// Diagnosis of attempt 35 (38.8% accuracy, 87.8% syntax):
//
// Root cause 1 — ACCURACY DROP (38.8% vs 49% in attempt 34):
//   The `braceInTail` and `openCount > closeCount` Phase-3 triggers fired on
//   examples where the model had already written a CORRECT plain span followed
//   by a curly-brace span (or vice versa). Phase 3 then replaced the correct
//   span with a constrained-generated one that was wrong or entered a repetition
//   loop (mode_O, mode_A clusters). Removing both triggers restores ~49% accuracy.
//
// Root cause 2 — REPETITION LOOPS (mode_A, mode_O):
//   `CloseSpanWithinBudget` doesn't apply repetition penalty; arithmetic
//   expressions like `int(expr) - 0 - 0 - 0 ...` are parser-valid so the
//   constrained loop continues until budget is exhausted. Fix: replace
//   `CloseSpanWithinBudget` in Phase 3 with a manual loop using
//   `RepetitionPenaltyStep` + `CloseSpanIfComplete` so repeated tokens are
//   penalised before each draw.
//
// Root cause 3 — FINAL_SPAN_UNCLOSED (5 examples, 2 new in attempt 35):
//   Two of the 5 were caused by bad triggers. The remaining 3 (same as attempt 34)
//   arise when the model writes `<<int(expr)>` (one `>` only) or writes `<<` near
//   budget exhaustion. Phase 3 fires (`closeCount == 0`) and opens a fresh `<<`;
//   the evaluator's `last_visible_span` takes the new closed one.
//
// Root cause 4 — CURLY-BRACE SPANS (7 in attempt 34, 1 in attempt 35):
//   Attempt 35's `braceInTail` fixed some but at the cost of accuracy.
//   Better approach: improve guidance to explicitly show the brace-dropping rule
//   with a worked example; don't trigger Phase 3 on curly-brace content.
//
// Strategy:
//   Phase 1: Full unconstrained generation (phase1Budget = maxSteps - spanBudget - 1).
//   Phase 3: Fire ONLY when `closeCount == 0` (no complete `<<...>>` span).
//     - `OpenConstrainedSpan` starts a fresh span.
//     - Inner loop: `CloseSpanIfComplete` per step; if not closed, draw next token
//       with `RepetitionPenaltyStep` to prevent `- 0 - 0` loops.
//   Guidance: explicit brace-stripping rule with example.
//
// Expected improvement: +5 pp syntax (repetition fix + better guidance), ~49% accuracy.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   [insideConstrained entry branch]:
//     CloseSpanWithinBudget postcondition guarantees
//     `insideOut ==> parser.IsValidPrefix(currentOut)` directly. ✓
//
//   [Phase 1 loop (else branch)]:
//     Loop invariant `!insideConstrainedOut` is established at branch entry and
//     unchanged inside the body (only UnconstrainedStep + append).
//     The implication is vacuously true every iteration. ✓
//
//   [Phase 3 — OpenConstrainedSpan]:
//     Sets insideConstrainedOut := true, currentConstrainedOut := [].
//     `parser.IsValidPrefix([])` holds by requires clause. ✓
//
//   [Phase 3 inner while — CloseSpanIfComplete]:
//     When closed: insideConstrainedOut := false; implication vacuous.
//     When not closed: state unchanged by CloseSpanIfComplete; invariant persists.
//
//   [Phase 3 inner while — RepetitionPenaltyStep + AppendConstrainedToken]:
//     RepetitionPenaltyStep is a ConstrainedStep variant; its postcondition
//     guarantees the returned token is parser-valid at currentConstrainedOut.
//     AppendConstrainedToken extends both generated and currentConstrainedOut;
//     IsTokenValidNext + AppendConstrainedToken postcondition preserves
//     parser.IsValidPrefix(currentConstrainedOut). ✓
//
//   [EOS break]: insideConstrainedOut may remain true; implication still holds
//     because it was valid at the last inner-loop iteration entry. ✓
//
// Invariant 2 (progress):
//   |generated| <= |generatedPrefix| + steps
//
//   [insideConstrained entry]: CloseSpanWithinBudget: |cg| <= |generated| + budget;
//     steps := budget; so |generated| <= |generatedPrefix| + steps. ✓
//
//   [Phase 1 loop]: Initialised: |generated| = |generatedPrefix|, steps = 0.
//     Each iteration increments steps by 1. EOS branch leaves generated unchanged;
//     non-EOS branch grows generated by 1. In both cases
//     |generated| <= |generatedPrefix| + steps. ✓
//
//   [Phase 3 OpenConstrainedSpan]: appends `<<` (+1 token), steps += 1. ✓
//
//   [Phase 3 inner while — CloseSpanIfComplete]: steps += 1; at most one `>>`
//     appended (+1 token). |generated| grows by at most 1 per step increment. ✓
//
//   [Phase 3 inner while — RepetitionPenaltyStep]: steps += 1. EOS: generated
//     unchanged (break). Non-EOS: AppendConstrainedToken grows generated by 1.
//     Either way |generated| grows by at most 1 per step increment. ✓
//
//   The total steps spent across all phases is bounded by maxSteps because each
//   guard check `steps < maxSteps` is done before every step increment. ✓
// CSD_PROOF_SKETCH_END

  generated := generatedPrefix;
  insideConstrainedOut := insideConstrained;
  currentConstrainedOut := currentConstrained;
  cost := 0;

  helpers.AppendTaskGuidance(lm,
    "Solve the math problem step by step. " +
    "The problem uses template variables like {n} or {price} inside curly braces. " +
    "IMPORTANT: In your final answer, drop the curly braces. Write n not {n}, price not {price}. " +
    "Place your final answer at the very end as <<int(expression)>>. " +
    "Inside << >>, use ONLY: plain variable names (NO braces), +, -, *, /, //, (, ), int(). " +
    "Example: if the problem mentions {count} items each worth {cost}, write <<int(count * cost)>>. " +
    "Do NOT include { or } inside << >>.");

  var spanBudget: nat := 44;
  var steps: nat := 0;

  if insideConstrainedOut {
    if steps < maxSteps {
      var remaining: nat := maxSteps - steps;
      var budget: nat := if remaining < spanBudget then remaining else spanBudget;
      var cg0, ci0, cc0 := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, budget
      );
      generated := cg0;
      insideConstrainedOut := ci0;
      currentConstrainedOut := cc0;
      steps := steps + budget;
    }
  } else {
    // Phase 1: Full unconstrained generation
    var phase1Budget: nat :=
      if maxSteps > spanBudget + 1 then maxSteps - spanBudget - 1 else maxSteps;

    while steps < phase1Budget
      invariant 0 <= steps <= phase1Budget
      invariant phase1Budget <= maxSteps
      invariant lm.ValidTokensIdsLogits()
      invariant !insideConstrainedOut
      invariant currentConstrainedOut == []
      invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
      invariant |generated| <= |generatedPrefix| + steps
      decreases phase1Budget - steps
    {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      generated := generated + [next];
    }

    // Phase 3: intervene only when no complete span was generated
    var generatedStr := CSDHelpers.PrefixToString(generated);
    var closeCount := CSDHelpers.CountSubstring(generatedStr, ">>");
    var needPhase3 := closeCount == 0;

    if needPhase3 && steps < maxSteps {
      // Open a fresh constrained span (evaluator takes last visible span)
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;

      // Inner constrained loop with repetition penalty to avoid `- 0 - 0 ...` loops
      while insideConstrainedOut && steps < maxSteps
        invariant lm.ValidTokensIdsLogits()
        invariant 0 <= steps <= maxSteps
        invariant !insideConstrainedOut ==> currentConstrainedOut == []
        invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
        invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
        invariant |generated| <= |generatedPrefix| + steps
        decreases maxSteps - steps
      {
        // Check completion first (costs 1 step when it closes, 0 otherwise;
        // we increment unconditionally to guarantee loop termination)
        var cg, ci, cc, closed := helpers.CloseSpanIfComplete(
          lm, parser, generated, currentConstrainedOut
        );
        steps := steps + 1;
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;

        if !closed && insideConstrainedOut && steps < maxSteps {
          // Generate one parser-valid token with repetition penalty
          var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
          var nextRep := helpers.RepetitionPenaltyStep(
            lm, parser, constrainedPrompt, currentConstrainedOut, generated, 2.0, eosToken
          );
          steps := steps + 1;
          if nextRep == eosToken {
            break;
          }
          var ag, ai, ac := helpers.AppendConstrainedToken(
            lm, parser, generated, currentConstrainedOut, nextRep
          );
          generated := ag;
          insideConstrainedOut := ai;
          currentConstrainedOut := ac;
        }
      }
    }
  }

  cost := steps;

